script:
test('eight units at 5.00 discounts only paid units to 27.00', function () {
  assert.deepEqual(code.priceLine({ sku: 'S1', units: 8, unitPrice: 5.00 }), { sku: 'S1', normalPrice: 40, freeUnits: 2, paidUnits: 6, lineTotal: 27.00 });
});
test('three units below four get only the 10 percent discount', function () {
  assert.deepEqual(code.priceLine({ sku: 'S2', units: 3, unitPrice: 5.00 }), { sku: 'S2', normalPrice: 15, freeUnits: 0, paidUnits: 3, lineTotal: 13.50 });
});
test('seven units waives one free unit and discounts six paid units', function () {
  assert.deepEqual(code.priceLine({ sku: 'S3', units: 7, unitPrice: 5.00 }), { sku: 'S3', normalPrice: 35, freeUnits: 1, paidUnits: 6, lineTotal: 27.00 });
});
test('zero units is allowed and returns a zero line total', function () {
  assert.deepEqual(code.priceLine({ sku: 'S4', units: 0, unitPrice: 5.00 }), { sku: 'S4', normalPrice: 0, freeUnits: 0, paidUnits: 0, lineTotal: 0.00 });
});
test('negative units is rejected as invalid field units', function () {
  assert.throws(function () {
    code.priceLine({ sku: 'S5', units: -1, unitPrice: 5.00 });
  }, /^invalid field: units$/);
});
test('one unit at 0.05 rounds half up once to 0.05', function () {
  assert.deepEqual(code.priceLine({ sku: 'S6', units: 1, unitPrice: 0.05 }), { sku: 'S6', normalPrice: 0.05, freeUnits: 0, paidUnits: 1, lineTotal: 0.05 });
});
test('1.125 rounds half up to 1.13 rather than half even', function () {
  assert.deepEqual(code.priceLine({ sku: 'S7', units: 1, unitPrice: 1.25 }), { sku: 'S7', normalPrice: 1.25, freeUnits: 0, paidUnits: 1, lineTotal: 1.13 });
});
test('exactly four units waives one and discounts three paid units', function () {
  assert.deepEqual(code.priceLine({ sku: 'S8', units: 4, unitPrice: 5.00 }), { sku: 'S8', normalPrice: 20, freeUnits: 1, paidUnits: 3, lineTotal: 13.50 });
});
test('five units waives one and discounts four paid units', function () {
  assert.deepEqual(code.priceLine({ sku: 'S9', units: 5, unitPrice: 5.00 }), { sku: 'S9', normalPrice: 25, freeUnits: 1, paidUnits: 4, lineTotal: 18.00 });
});
test('nine units waives two and discounts seven paid units', function () {
  assert.deepEqual(code.priceLine({ sku: 'S10', units: 9, unitPrice: 5.00 }), { sku: 'S10', normalPrice: 45, freeUnits: 2, paidUnits: 7, lineTotal: 31.50 });
});
test('eleven units waives two and discounts nine paid units', function () {
  assert.deepEqual(code.priceLine({ sku: 'S11', units: 11, unitPrice: 5.00 }), { sku: 'S11', normalPrice: 55, freeUnits: 2, paidUnits: 9, lineTotal: 40.50 });
});
test('exactly twelve units waives three and discounts nine paid units', function () {
  assert.deepEqual(code.priceLine({ sku: 'S12', units: 12, unitPrice: 5.00 }), { sku: 'S12', normalPrice: 60, freeUnits: 3, paidUnits: 9, lineTotal: 40.50 });
});
test('thirteen units waives three and discounts ten paid units', function () {
  assert.deepEqual(code.priceLine({ sku: 'S13', units: 13, unitPrice: 5.00 }), { sku: 'S13', normalPrice: 65, freeUnits: 3, paidUnits: 10, lineTotal: 45.00 });
});
test('four units at 0.05 rounds the paid total once to 0.14', function () {
  assert.deepEqual(code.priceLine({ sku: 'S14', units: 4, unitPrice: 0.05 }), { sku: 'S14', normalPrice: 0.20, freeUnits: 1, paidUnits: 3, lineTotal: 0.14 });
});
test('a zero unit price returns a zero line total', function () {
  assert.deepEqual(code.priceLine({ sku: 'S15', units: 4, unitPrice: 0 }), { sku: 'S15', normalPrice: 0, freeUnits: 1, paidUnits: 3, lineTotal: 0.00 });
});
test('a negative unit price is rejected even when units is zero', function () {
  assert.throws(function () {
    code.priceLine({ sku: 'S16', units: 0, unitPrice: -5 });
  }, /^invalid field: unitPrice$/);
});
